package com.exito.chop;
import android.app.*;import android.content.*;import android.content.pm.ServiceInfo;import android.os.*;import java.io.*;import java.net.*;import java.nio.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.*;import java.util.concurrent.atomic.AtomicBoolean;
public final class NetworkInputService extends Service {
 static volatile boolean active;static volatile String address="Iniciando…";ServerSocket server;volatile boolean running;LiveBuffer buffer;String token;long lastPublish,lastAnalysis;final AtomicBoolean queued=new AtomicBoolean();
 @Override public IBinder onBind(Intent i){return null;}@Override public int onStartCommand(Intent i,int flags,int start){if(i!=null&&"stop".equals(i.getAction())){stopSelf();return START_NOT_STICKY;}if(running)return START_NOT_STICKY;Engine e=Engine.get(this);if(e.busy||e.capturing){stopSelf();return START_NOT_STICKY;}if(Build.VERSION.SDK_INT>=34)startForeground(203,Notifs.make(this,"Audio del ordenador · Wi-Fi local",NetworkInputService.class),ServiceInfo.FOREGROUND_SERVICE_TYPE_SPECIAL_USE);else startForeground(203,Notifs.make(this,"Audio del ordenador · Wi-Fi local",NetworkInputService.class));token=UUID.randomUUID().toString().replace("-","");buffer=new LiveBuffer(44100,32);e.history.begin("Entrada del ordenador");e.slots.save();e.padParams=PadParams.defaults();e.selected=0;e.semitones=0;e.tempo=1;e.liveBuffer=buffer;e.liveMode=e.capturing=true;e.chopMode=PadChops.EMPTY;e.padMarking=true;e.manualTransform=false;e.liveReady=e.liveMetadataReady=e.liveMetadataOverride=false;e.inputRemote=true;e.inputAll=e.inputWeb=false;e.inputLabel="Ordenador";e.inputPrompt=false;e.liveStatus="Ordenador · esperando audio por Wi-Fi";running=active=true;e.changed();new Thread(this::serve,"EXITO-PC-input").start();return START_NOT_STICKY;}
 static String ip(){try{Enumeration<NetworkInterface> all=NetworkInterface.getNetworkInterfaces();while(all.hasMoreElements()){NetworkInterface n=all.nextElement();if(!n.isUp()||n.isLoopback())continue;Enumeration<InetAddress> a=n.getInetAddresses();while(a.hasMoreElements()){InetAddress p=a.nextElement();if(p instanceof Inet4Address&&p.isSiteLocalAddress())return p.getHostAddress();}}}catch(Exception ignored){}return "IP-del-movil";}
 static String line(InputStream in)throws IOException{ByteArrayOutputStream b=new ByteArrayOutputStream();int c;while((c=in.read())>=0){if(c==10)break;if(c!=13)b.write(c);if(b.size()>8192)throw new IOException("Cabecera demasiado larga");}return b.toString("US-ASCII");}
 void reply(OutputStream out,int status,String type,byte[] data)throws IOException{String h="HTTP/1.1 "+status+" "+(status==200?"OK":"Error")+"\r\nContent-Type: "+type+"\r\nContent-Length: "+data.length+"\r\nConnection: close\r\nCache-Control: no-store\r\n\r\n";out.write(h.getBytes(StandardCharsets.US_ASCII));out.write(data);out.flush();}
 void serve(){Engine e=Engine.get(this);try{server=new ServerSocket();server.setReuseAddress(true);server.bind(new InetSocketAddress(8765));address="http://"+ip()+":8765/?token="+token;e.message("Puente PC activo: abre su enlace en el ordenador");while(running){try(Socket client=server.accept()){client.setSoTimeout(5000);InputStream in=client.getInputStream();OutputStream out=client.getOutputStream();String[] req=line(in).split(" ");if(req.length<2)continue;String path=req[1];int length=0;for(int h=0;h<64;h++){String v=line(in);if(v.isEmpty())break;if(v.toLowerCase(Locale.US).startsWith("content-length:"))length=Integer.parseInt(v.substring(15).trim());}String supplied="";int t=path.indexOf("token=");if(t>=0)supplied=path.substring(t+6).split("&",2)[0];if(!MessageDigest.isEqual(token.getBytes(StandardCharsets.US_ASCII),supplied.getBytes(StandardCharsets.US_ASCII))){reply(out,403,"text/plain",new byte[0]);continue;}
 if(req[0].equals("POST")&&path.startsWith("/pcm?")&&length>0&&length<=65536&&length%4==0){byte[] raw=new byte[length];new DataInputStream(in).readFully(raw);short[] pcm=new short[length/2];ByteBuffer.wrap(raw).order(ByteOrder.LITTLE_ENDIAN).asShortBuffer().get(pcm);int peak=0;for(short s:pcm)peak=Math.max(peak,Math.abs((int)s));if(peak>=8||buffer.frames()>0)buffer.append(pcm,pcm.length);e.inputDb=(float)Math.max(-96,20*Math.log10(Math.max(1,peak)/32768.));e.captureSeconds=(int)(buffer.frames()/44100);e.analyseInput(buffer);e.liveStatus=peak>=8?"Ordenador · audio entrando · últimos "+Math.min(e.captureSeconds,e.captureLimit)+" s":"Ordenador · sin señal audible";if(buffer.frames()>1024)publish();else e.changed();reply(out,200,"text/plain",new byte[]{79,75});}
 else if(req[0].equals("GET")&&path.startsWith("/bridge.zip?")){try(InputStream asset=getAssets().open("desktop.zip")){ByteArrayOutputStream b=new ByteArrayOutputStream();byte[] block=new byte[16384];int n;while((n=asset.read(block))>0)b.write(block,0,n);reply(out,200,"application/zip",b.toByteArray());}}
 else if(req[0].equals("GET")&&path.startsWith("/?")){String page="<!doctype html><meta charset=utf-8><title>EXITO PC</title><body style='background:#0d1016;color:#c0e72c;font:20px system-ui;max-width:700px;margin:50px auto'><h1>EXITO / PC BRIDGE</h1><p>Ambos equipos deben estar en la misma red.</p><p><a style='color:#25bdec' href='/bridge.zip?token="+token+"' download='ChopGO_CHOP_PC.zip'>1. Descargar el puente</a></p><p>2. Descomprime. Windows: INICIAR_WINDOWS.bat. macOS/Linux: python3 server.py.</p><p>3. Pega este enlace en el puente y comparte una pestaña con audio:</p><textarea style='width:100%;height:100px'>"+address+"</textarea><p>Solo audio PCM por la red local; no se envía la imagen de pantalla.</p>";reply(out,200,"text/html; charset=utf-8",page.getBytes(StandardCharsets.UTF_8));}else reply(out,404,"text/plain",new byte[0]);}catch(Exception error){if(running)e.message("Puente PC: "+Engine.reason(error));}}}catch(Exception error){if(running)e.message("No se pudo abrir entrada PC: "+Engine.reason(error));}finally{stopSelf();}}
 void publish(){Engine e=Engine.get(this);if(e.livePadTake!=null){LivePadTake take=e.livePadTake;e.waveform=Dsp.peaks(buffer.window(1).pcm,1024);e.changed();if(take.full())e.main.post(()->{if(e.livePadTake==take)e.finishPadMarking(true);});return;}long now=SystemClock.elapsedRealtime();if(now-lastPublish<600||e.busy||!queued.compareAndSet(false,true))return;lastPublish=now;final LiveBuffer.Window w=buffer.window(e.captureLimit);final float speed=e.tempo,pitch=e.semitones;final int index=e.slots.active;final int[] cuts=PadChops.isMode(e.chopMode)?new int[]{0,w.pcm.length/2}:e.chopMode.equals("manual")?w.manualCuts:Dsp.chops(w.pcm,44100,e.chopMode.equals("threshold")?0:e.requestedChops,e.thresholdDb);e.worker.execute(()->{try{short[] rendered=Dsp.stretch(w.pcm,44100,speed,(float)Math.pow(2,pitch/12.));float[] peaks=Dsp.peaks(w.pcm,4096);int[] meta=null;if(meta!=null)lastAnalysis=now;e.main.post(()->{try{if(!running||e.livePadTake!=null||e.liveBuffer!=buffer||e.busy||index!=e.slots.active||e.tempo!=speed||e.semitones!=pitch)return;e.source=w.pcm;e.rendered=rendered;e.rate=44100;e.cuts=cuts;e.waveform=peaks;e.selected=Math.min(e.selected,cuts.length-2);e.video=null;e.name="Ordenador · entrada Wi-Fi";e.liveReady=true;if(meta!=null&&!e.liveMetadataOverride){e.liveMetadata(meta[0],meta[1]);}e.changed();}finally{queued.set(false);}});}catch(Throwable error){queued.set(false);e.message("PC: "+Engine.reason(error));}});}
 @Override public void onDestroy(){running=active=false;try{if(server!=null)server.close();}catch(Exception ignored){}Engine e=Engine.get(this);if(buffer!=null&&e.liveBuffer==buffer){if(e.livePadTake!=null)e.finishPadMarking(false);e.liveBuffer=null;e.capturing=e.liveMode=false;e.inputDb=-96;e.message("Ordenador desconectado; último fragmento disponible");}stopForeground(STOP_FOREGROUND_REMOVE);super.onDestroy();}
}
